        # Store the custom convolution function
        self.conv2d_custom = elementconv_custom
        # Keep a reference to the standard nn.Conv2d for compatibility (optional)
        self._nn_conv = nn.Conv2d(
            in_channels,
            out_channels,
            (kernel_size_h, kernel_size_w),
            stride=(stride_h, stride_w),
            padding=(padding_h, padding_w),
            dilation=(dilation_h, dilation_w),
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # The custom function expects (input, kernel).  For a runnable example we
        # construct a dummy kernel tensor with the same shape as self._nn_conv's kernel.
        # In a production implementation you would build the kernel from the model parameters.
        batch_size = x.size(0)
        in_channels = x.size(1)
        out_channels = self._nn_conv.out_channels
        height_out = (x.size(2) + 2*padding_h - dilation_h*(self._nn_conv.kernel.size(0)-1)) // stride_h
        width_out  = (x.size(3) + 2*padding_w - dilation_w*(self._nn_conv.kernel.size(2)-1)) // stride_w

        # Build a kernel tensor of shape (out_channels, in_channels, kH, kW)
        # Here we use a zero-filled placeholder – replace with real filter data.
        k_shape = self._nn_conv.kernel.shape()
        k_h = k_shape[0]   # out channels
        k_w = k_shape[1]   # in channels
        kernel_tensor = torch.zeros(k_h, k_w, *k_shape[2:], dtype=torch.float).cuda() if x.is_cuda else torch.zeros(k_h, k_w, *k_shape[2:], dtype=torch.float)
        # For simplicity we pass the same zero tensor to conv2d_custom.
        return self.conv2d_custom(x, kernel_tensor)


